content.content:
1	/* ============================================
2	   共通リセット
3	   ============================================ */
4	html { scroll-behavior: smooth; }
5	@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { animation: none !important; } }
6	* { box-sizing: border-box; }
7	body { margin: 0; font-family: "Zen Kaku Gothic New", "Archivo", system-ui, sans-serif; -webkit-font-smoothing: antialiased; }
8	a { color: inherit; text-decoration: none; }
9	
10	/* ページテーマ（body class="page-xxx"） */
11	/* page-portfolio（404）・page-privacy はTOPページと同じネイビー×オレンジ配色。page-pianist・page-horror は現行デザインを維持（別途リニューアル予定のため変更しない） */
12	body.page-portfolio { background: #FFFFFF; color: #172E4A; }
13	body.page-privacy { background: #FFFFFF; color: #172E4A; }
14	body.page-pianist { background: #08080A; color: #F2EFE9; }
15	body:has(.pn-shell) {
16	  color: #F2EFE9;
17	  background: linear-gradient(180deg,rgba(8,8,10,0.4),rgba(8,8,10,0.65)), url("images/25253200_l.webp") center / cover no-repeat fixed, #08080A;
18	}
19	body:has(.top-shell) {
20	  background: #FFFFFF;
21	}
22	body.page-portfolio a:hover { color: #DC8541; }
23	body.page-privacy a:hover { color: #DC8541; }
24	body.page-pianist a:hover { color: #E4C97E; }
25	.pn-shell a:hover { color: #E4C97E; }
26	body.page-portfolio ::selection,
27	body.page-privacy ::selection { background: #F6D3B0; color: #172E4A; }
28	
29	body.page-horror { background: #07070A; color: #D6D2CB; }
30	body.page-horror a:hover { color: #9B2C22; }
31	
32	/* ============================================
33	   キーフレームアニメーション
34	   ============================================ */
35	@keyframes fadeup { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
36	@keyframes flick { 0%,100% { opacity: .85; } 47% { opacity: .85; } 48% { opacity: .35; } 52% { opacity: .9; } 70% { opacity: .6; } }
37	
38	/* ============================================
39	   共通ユーティリティ
40	   ============================================ */
41	.container { max-width: 1180px; margin: 0 auto; padding-inline: clamp(20px,5vw,64px); }
42	
43	.tag-row { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px; }
44	.tag { display: inline-flex; align-items: center; font-size: 12px; letter-spacing: 0.01em; font-weight: 500; color: #3E4A5C; border: none; border-radius: 999px; padding: 8px 16px; background: rgba(23,46,74,0.07); white-space: nowrap; }
45	.tag--on-dark { color: #EAF0F6; background: rgba(255,255,255,0.09); }
46	
47	.btn-group { display: flex; flex-wrap: wrap; gap: 14px; align-items: center; }
48	.btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; font-weight: 700; font-size: 14px; letter-spacing: 0.09em; padding: 20px 34px; border-radius: 999px; border: 3px solid transparent; cursor: pointer; transition: background .25s ease, border-color .25s ease, color .25s ease, transform .15s ease, box-shadow .15s ease; white-space: nowrap; }
49	.btn:hover { transform: translate(3px,3px); }
50	.btn:active { transform: translate(5px,5px); }
51	.btn--primary { background: #DC8541; color: #FFFFFF; box-shadow: 5px 5px 0 #172E4A; }
52	.btn--primary:hover { background: #C06E2E; box-shadow: 2px 2px 0 #172E4A; }
53	.btn--primary:active { box-shadow: 0 0 0 #172E4A; }
54	.btn--secondary { background: #FFFFFF; color: #172E4A; border-color: #172E4A; box-shadow: 5px 5px 0 #DC8541; }
55	.btn--secondary:hover { background: #172E4A; color: #FFFFFF; box-shadow: 2px 2px 0 #DC8541; }
56	.btn--secondary:active { box-shadow: 0 0 0 #DC8541; }
57	.btn--sm { padding: 13px clamp(14px,1.6vw,22px); font-size: 12px; font-weight: 600; box-shadow: 4px 4px 0 #172E4A; }
58	.btn--sm:hover { box-shadow: 1px 1px 0 #172E4A; }
59	.btn--sm:active { box-shadow: 0 0 0 #172E4A; }
60	
61	/* ============================================
62	   shell（各ページ共通の外枠カード／pianist・horrorと共有のため触らない）
63	   ============================================ */
64	.shell {
65	  container-type: inline-size;
66	  max-width: 375px;
67	  margin: 0 auto;
68	  min-height: 100svh;
69	  position: relative;
70	  overflow-x: hidden;
71	  display: flex;
72	  flex-direction: column;
73	  background: #F5F8FC;
74	  box-shadow: 0 0 80px rgba(18,36,63,0.16);
75	}
76	.shell--muted { background: #F0F5FA; }
77	.shell--dark { background: #0B0B0C; box-shadow: 0 0 80px rgba(0,0,0,0.5); }
78	
79	.skip-link { position: absolute; left: -9999px; top: 0; background: #12243F; color: #F5F8FC; padding: 12px 18px; z-index: 200; }
80	.skip-link:focus { left: 12px; top: 12px; }
81	
82	/* ============================================
83	   page-header（下層ページの戻るリンクヘッダー／pianist・horrorと共有のため触らない）
84	   ============================================ */
85	.page-header { padding: 24px clamp(20px,6cqw,80px); display: flex; justify-content: space-between; align-items: center; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; }
86	.page-header--dark { color: #8A8580; }
87	.page-header__back { display: inline-flex; align-items: center; gap: 10px; transition: gap .3s ease; }
88	.page-header__back:hover { gap: 18px; }
89	.page-header__label { color: #7B8DA6; }
90	
91	/* ============================================
92	   page-footer（下層ページ共通フッター／pianist・horrorと共有のため触らない）
93	   ============================================ */
94	.page-footer { padding: clamp(40px,5cqw,72px) clamp(20px,6cqw,80px); border-top: 1px solid #D3DEEB; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #7B8DA6; margin-top: auto; }
95	.page-footer--dark { border-top-color: #1E1D1D; color: #5A5652; }
96	
97	/* ============================================
98	   top-shell（TOPページのラッパー／固定フレームは使わずフル幅レスポンシブ／
99	   「手描きポップ」デザイン：太め枠線・オフセット影・回転バッジが基調）
100	   ============================================ */
101	.top-shell {
102	  min-height: 100svh;
103	  display: flex;
104	  flex-direction: column;
105	}
106	body:has(.top-shell) a:hover { color: #DC8541; }
107	body:has(.top-shell) ::selection { background: #F6D3B0; color: #172E4A; }
108	
109	@keyframes prupru {
110	  0% { transform: rotate(-2deg) translate(0,0); }
111	  12% { transform: rotate(2.4deg) translate(2px,-1px); }
112	  26% { transform: rotate(-3.2deg) translate(-2px,1px); }
113	  40% { transform: rotate(2.6deg) translate(2px,1px); }
114	  54% { transform: rotate(-2.4deg) translate(-1px,-1px); }
115	  68% { transform: rotate(1.6deg) translate(1px,0); }
116	  84% { transform: rotate(-2.4deg) translate(-1px,0); }
117	  100% { transform: rotate(-2deg) translate(0,0); }
118	}
119	
120	/* ============================================
121	   site-header（TOPページ固定ヘッダー／DCコンポーネントの状態クラス hero-nav / menu は名称を維持）
122	   ============================================ */
123	.hero-nav {
124	  position: sticky; top: 0; z-index: 96;
125	  display: flex; align-items: center; justify-content: space-between;
126	  gap: 20px;
127	  padding: 16px clamp(18px,5vw,56px);
128	  background: rgba(255,255,255,0.93);
129	  border-bottom: 4px solid #172E4A;
130	  backdrop-filter: blur(10px);
131	  -webkit-backdrop-filter: blur(10px);
132	}
133	.hero-nav__h1 { margin: 0; }
134	.hero-nav__logo { display: inline-flex; align-items: center; gap: 12px; line-height: 1; transition: opacity .2s ease; }
135	.hero-nav__logo-mark { width: 34px; height: 34px; object-fit: contain; display: block; flex: none; }
136	.hero-nav__logo-text { display: inline-flex; align-items: baseline; gap: 12px; }
137	.hero-nav__logo-main { font-size: 18px; letter-spacing: 0.09em; color: #172E4A; font-weight: 500; transition: color .2s ease; }
138	.hero-nav__logo-sub { font-size: 9px; letter-spacing: 0.26em; color: #DC8541; transition: color .2s ease; }
139	.hero-nav__logo:hover .hero-nav__logo-main { color: #DC8541; }
140	.hero-nav__logo:hover .hero-nav__logo-sub { color: #172E4A; }
141	
142	.hero-nav__nav { display: none; }
143	.hero-nav__nav-list { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; gap: clamp(14px,1.8vw,28px); font-size: 13.5px; color: #3E4A5C; }
144	.hero-nav__nav-list a { transition: color .2s ease; }
145	.hero-nav__nav-list a:hover { color: #DC8541; }
146	.hero-nav__actions { display: flex; align-items: center; gap: 10px; }
147	.hero-nav__cta--compact { display: none; }
148	
149	.hero-nav__toggle {
150	  width: 44px; height: 44px; display: flex; flex-direction: column;
151	  justify-content: center; align-items: center; gap: 6px; background: none; border: none;
152	  cursor: pointer; padding: 0; flex: none;
153	}
154	.hero-nav__bar {
155	  display: block; height: 2px; width: 22px; border-radius: 2px; background: #172E4A;
156	  transition: transform .35s cubic-bezier(.2,.7,.2,1), opacity .2s ease;
157	}
158	.hero-nav.is-open .hero-nav__bar--top { transform: translateY(4px) rotate(45deg); }
159	.hero-nav.is-open .hero-nav__bar--bottom { transform: translateY(-4px) rotate(-45deg); }
160	
161	@media (min-width: 880px) {
162	  .hero-nav__nav { display: block; }
163	  .hero-nav__toggle { display: none; }
164	  .hero-nav__cta--compact { display: none; }
165	}
166	@media (max-width: 879px) {
167	  .hero-nav__cta--full { display: none; }
168	  .hero-nav__cta--compact { display: inline-flex; }
169	}
170	
171	/* ============================================
172	   menu（ハンバーガーで開くフルスクリーンナビ／DCコンポーネントの状態クラス menu は名称を維持）
173	   ============================================ */
174	.menu {
175	  position: fixed; inset: 0; z-index: 95;
176	  background: linear-gradient(160deg,#1B335A 0%,#172E4A 45%,#0F2038 100%);
177	  display: flex; flex-direction: column;
178	  overflow-y: auto; -webkit-overflow-scrolling: touch;
179	  padding: 96px clamp(24px,7vw,56px) 48px;
180	  transition: opacity .4s ease, visibility .4s ease;
181	  opacity: 0; visibility: hidden; pointer-events: none;
182	}
183	.menu.is-open { opacity: 1; visibility: visible; pointer-events: auto; }
184	.menu__cta { margin-bottom: clamp(30px,6vw,48px); }
185	.menu__inner { display: grid; gap: clamp(28px,6vw,44px); width: 100%; max-width: 420px; }
186	.menu__inner > div + div { border-top: 2px dashed rgba(224,185,143,0.28); padding-top: clamp(26px,6vw,40px); }
187	.menu__group-title { display: inline-flex; align-items: center; gap: 10px; font-size: 11px; letter-spacing: 0.24em; color: #E0B98F; margin: 0 0 18px; }
188	.menu__group-title::before { content: ""; width: 16px; height: 2px; background: #DC8541; border-radius: 2px; }
189	.menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-weight: 700; font-size: 19px; line-height: 1.25; color: #FFFFFF; counter-reset: menu-index; }
190	.menu__nav-list li { counter-increment: menu-index; }
191	.menu__nav-list a {
192	  display: flex; align-items: center; gap: 14px;
193	  padding: 12px 10px; margin-inline: -10px; border-radius: 14px;
194	  transition: transform .3s cubic-bezier(.2,.7,.2,1), color .25s ease, background .25s ease;
195	}
196	.menu__nav-list a::before {
197	  content: counter(menu-index, decimal-leading-zero);
198	  font-family: ui-monospace,Menlo,monospace; font-size: 11px; font-weight: 400;
199	  letter-spacing: 0.08em; color: #DC8541;
200	}
201	.menu__nav-list a::after {
202	  content: "→"; margin-left: auto; font-size: 15px; color: #DC8541;
203	  opacity: 0; transform: translateX(-8px); transition: opacity .25s ease, transform .25s ease;
204	}
205	.menu__nav-list a:hover { color: #F6D3B0; background: rgba(255,255,255,0.06); transform: translateX(6px); }
206	.menu__nav-list a:hover::after { opacity: 1; transform: translateX(0); }
207	.menu__personal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
208	.menu__personal-link {
209	  display: block; padding: 14px 16px; margin-inline: -16px; border-radius: 16px;
210	  border: 1px solid rgba(224,185,143,0.22);
211	  transition: border-color .3s ease, background .3s ease, transform .3s ease;
212	}
213	.menu__personal-link:hover { background: rgba(255,255,255,0.05); border-color: rgba(224,185,143,0.5); transform: translateX(4px); }
214	.menu__personal-link-title { display: block; font-size: 15px; font-weight: 700; color: #FFFFFF; transition: color .3s ease; }
215	.menu__personal-link:hover .menu__personal-link-title { color: #DC8541; }
216	.menu__personal-link-desc { display: block; font-size: 12px; color: #9DB4CD; margin-top: 4px; }
217	.menu__credit { margin: 36px 0 0; font-size: 11px; letter-spacing: 0.16em; color: #6B85A6; }
218	
219	@media (min-width: 880px) {
220	  .menu { display: none; }
221	}
222	
223	/* ============================================
224	   section 基本パターン
225	   ============================================ */
226	.section { position: relative; padding-block: clamp(66px,9vw,120px); background: #FFFFFF; overflow: hidden; }
227	.section--alt { background: #FFF3E6; }
228	.section--dark { background: #172E4A; color: #EAF0F6; }
229	.section--tight { padding-block: clamp(40px,6vw,80px); }
230	
231	.section__head-row { display: flex; flex-wrap: wrap; align-items: center; gap: clamp(22px,4vw,48px); margin-bottom: clamp(34px,5vw,56px); }
232	.section__head { flex: 1 1 320px; min-width: 0; max-width: 760px; margin-bottom: clamp(32px,5vw,64px); }
233	.section__head-row .section__head { margin-bottom: 0; }
234	.section__head--center { margin-inline: auto; text-align: center; }
235	.section__body { position: relative; padding-top: clamp(48px,9vw,84px); }
236	.section__deco {
237	  position: absolute; top: 0; right: 0; z-index: 2; pointer-events: none;
238	  width: clamp(120px,17vw,200px); aspect-ratio: 1/1;
239	  transform: translate(10%,-55%);
240	}
241	.section__deco img { width: 100%; height: 100%; object-fit: cover; display: block; border-radius: 50%; border: 4px solid #FFFFFF; box-shadow: 0 12px 26px rgba(23,46,74,0.18); }
242	
243	@media (max-width: 480px) {
244	  .section__deco { width: clamp(84px,26vw,120px); }
245	}
246	.section__eyebrow {
247	  display: inline-block; margin: 0 0 18px; font-weight: 700; font-size: 11px; line-height: 1;
248	  letter-spacing: 0.22em; color: #FFFFFF; background: #172E4A; padding: 9px 16px; border-radius: 999px;
249	  transform: rotate(-2deg);
250	}
251	.section--dark .section__eyebrow, .section--cta .section__eyebrow { background: #DC8541; color: #172E4A; }
252	.section__heading { margin: 0; font-weight: 900; font-size: clamp(26px,3.6vw,44px); line-height: 1.42; letter-spacing: -0.01em; color: #172E4A; }
253	.section--dark .section__heading, .section--cta .section__heading { color: #FFFFFF; }
254	.section__lead { margin: 18px 0 0; font-size: 15px; line-height: 2; color: #56637A; }
255	.section--dark .section__lead { color: #C3D0E0; }
256	.section__lead--note { font-size: 13px; opacity: .82; }
257	.section__pretitle { margin: 0 0 10px; font-weight: 900; font-size: clamp(18px,2.4vw,24px); line-height: 1.5; color: #DC8541; }
258	
259	/* ============================================
260	   hero
261	   ============================================ */
262	.hero { padding-top: clamp(48px,8vw,92px); padding-bottom: clamp(60px,9vw,104px); background: linear-gradient(180deg,#FFFFFF 0%,#FFF3E6 100%); overflow: hidden; }
263	.hero__inner { display: grid; gap: clamp(40px,6vw,64px); align-items: center; }
264	.hero__audience { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 0 0 16px; padding: 8px 16px; border-radius: 999px; background: rgba(220,133,65,0.12); }
265	.hero__audience-en { font-size: 10px; letter-spacing: 0.18em; color: #DC8541; font-weight: 700; }
266	.hero__audience-ja { font-size: 12.5px; font-weight: 700; color: #172E4A; }
267	.hero__eyebrow { display: flex; align-items: center; gap: 14px; font-size: 11.5px; letter-spacing: 0.22em; color: #8A7B6C; margin: 0 0 clamp(20px,3vw,26px); }
268	.hero__eyebrow-line { width: 7px; height: 7px; border-radius: 50%; background: #DC8541; }
269	.hero__heading { margin: 0; font-weight: 900; font-size: clamp(26px,4.2vw,52px); line-height: 1.45; letter-spacing: -0.01em; color: #172E4A; }
270	.hero__line { display: block; }
271	.hero__highlight { position: relative; display: inline-block; color: #172E4A; }
272	.hero__highlight::after { content: ""; position: absolute; left: 0; right: 0; bottom: 6px; height: 12px; background: rgba(220,133,65,0.24); border-radius: 6px; z-index: -1; }
273	.hero__lead { margin: clamp(24px,3vw,32px) 0 0; font-size: 15px; line-height: 2.05; color: #56637A; max-width: 46ch; }
274	.hero__tags { margin-top: clamp(22px,3vw,30px); }
275	.hero__actions { margin-top: clamp(28px,4vw,38px); }
276	
277	.hero__visual { position: relative; display: flex; justify-content: center; }
278	.hero__photo {
279	  position: relative; width: 100%; max-width: 320px; margin: 0 auto; aspect-ratio: 4/5;
280	  border: 2.5px solid #172E4A; border-radius: 170px 170px 26px 26px;
281	  background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px);
282	  display: flex; align-items: center; justify-content: center; overflow: hidden;
283	}
284	.hero__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #8A93A3; background: #FFFFFF; padding: 6px 14px; border: 1px solid #E3E6EB; border-radius: 999px; }
285	
286	@media (min-width: 860px) {
287	  .hero__inner { grid-template-columns: minmax(0,1fr) 320px; }
288	  .hero__visual { order: 2; }
289	}
290	
291	/* ============================================
292	   tile-grid（PROBLEMS / TEAM / WORK STYLE 共通／太枠＋オフセット影のポップカード）
293	   ============================================ */
294	.tile-grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2,1fr); gap: 16px; }
295	.tile { display: flex; flex-direction: column; align-items: center; gap: 18px; text-align: center; background: #FFFFFF; border: 3px solid #172E4A; border-radius: 24px; padding: clamp(24px,3vw,32px); box-shadow: 6px 6px 0 #172E4A; }
296	.tile__icon img { width: auto; height: clamp(60px,8vw,92px); object-fit: contain; display: block; }
297	.tile__text { margin: 0; font-size: 14.5px; line-height: 1.85; color: #172E4A; font-weight: 500; }
298	.tile__label { font-size: 14px; font-weight: 700; line-height: 1.6; color: #172E4A; }
299	
300	.tile-grid--dot { display: flex; flex-wrap: wrap; }
301	.tile-grid--dot .tile--row { flex: 0 1 auto; flex-direction: row; align-items: center; justify-content: flex-start; gap: 14px; text-align: left; box-shadow: none; padding: 20px 22px; }
302	.tile__dot { flex: none; width: 28px; height: 28px; border-radius: 50%; background: rgba(220,133,65,0.14); display: flex; align-items: center; justify-content: center; }
303	.tile__dot::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: #DC8541; }
304	
305	@media (min-width: 640px) {
306	  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
307	}
308	@media (min-width: 880px) {
309	  .tile-grid--6 { grid-template-columns: repeat(6,1fr); }
310	  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
311	}
312	
313	/* ============================================
314	   scope-highlight（SCOPE／常時表示の主要3項目）
315	   ============================================ */
316	.scope-highlight { list-style: none; margin: 0 0 clamp(28px,4vw,40px); padding: 0; display: grid; gap: 14px; }
317	.scope-highlight__item { background: #FFFFFF; border: 3px solid #172E4A; border-left-width: 10px; border-left-color: #DC8541; border-radius: 18px; padding: 22px 24px; }
318	.scope-highlight__title { margin: 0; font-weight: 700; font-size: 16px; color: #172E4A; }
319	.scope-highlight__text { margin: 10px 0 0; font-size: 13.5px; line-height: 1.9; color: #56637A; }
320	
321	@media (min-width: 880px) {
322	  .scope-highlight { grid-template-columns: repeat(3,1fr); }
323	}
324	
325	/* ============================================
326	   team-scope（TEAM／Web Directionを主役にした情報階層）
327	   ============================================ */
328	.team-scope { display: grid; gap: 20px; }
329	.team-scope__primary { display: flex; flex-direction: column; align-items: center; gap: 14px; text-align: center; background: #172E4A; color: #FFFFFF; border: 3px solid #172E4A; border-radius: 26px; padding: clamp(28px,4vw,40px); box-shadow: 8px 8px 0 #A85A1E; }
