content.content:
400	
401	/* ============================================
402	   philosophy（PHILOSOPHY）
403	   ============================================ */
404	.chain { display: flex; flex-direction: column; gap: 14px; align-items: stretch; max-width: 920px; margin: 0 auto; }
405	.chain__node { flex: 1; min-width: 0; background: #1E3A5C; color: #FFFFFF; border: 3px solid #E0B98F; border-radius: 22px; padding: clamp(22px,3vw,30px); text-align: center; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; }
406	.chain__node--accent { background: #FFFFFF; color: #172E4A; border: none; box-shadow: 8px 8px 0 #A85A1E; }
407	.chain__icon img { width: clamp(60px,8vw,92px); height: clamp(60px,8vw,92px); object-fit: contain; display: block; }
408	.chain__role { margin: 0; font-weight: 600; font-size: 13px; letter-spacing: 0.1em; color: inherit; }
409	.chain__node--accent .chain__role { color: #C06E2E; }
410	.chain__points { list-style: none; margin: 16px 0 0; padding: 0; display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; }
411	.chain__points .tag { font-size: 11px; padding: 6px 13px; background: rgba(23,46,74,0.08); }
412	.chain__arrow { display: none; }
413	
414	.philosophy__points { list-style: none; margin: 22px 0 0; padding: 0; display: grid; gap: 12px; max-width: 40ch; }
415	.philosophy__points li { font-size: 14.5px; color: #FFFFFF; padding-left: 22px; position: relative; }
416	.philosophy__points li::before { content: ""; position: absolute; left: 0; top: 8px; width: 6px; height: 6px; border-radius: 50%; background: #DC8541; }
417	
418	@media (min-width: 820px) {
419	  .chain { flex-direction: row; }
420	  .chain__arrow { display: flex; align-items: center; justify-content: center; flex: none; color: #DC8541; font-size: 18px; }
421	}
422	
423	/* ============================================
424	   work-card（WORKS／クリックでモーダル詳細を開くポップカード）
425	   ============================================ */
426	.work-grid { display: grid; grid-template-columns: 1fr; gap: 26px; }
427	.work-card { display: flex; flex-direction: column; cursor: pointer; background: #FFFFFF; border: 3px solid #172E4A; border-radius: 26px; overflow: hidden; box-shadow: 8px 8px 0 #172E4A; transition: transform .2s ease; }
428	.work-card:hover { transform: translate(-2px,-2px); }
429	.work-card__media { position: relative; aspect-ratio: 4/3; background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px); overflow: hidden; }
430	.work-card__media img { display: block; width: 100%; height: 100%; object-fit: cover; }
431	.work-card__media--placeholder { display: flex; align-items: center; justify-content: center; }
432	.work-card__media--placeholder span { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 6px 12px; border: 1px solid #E3E6EB; border-radius: 999px; }
433	.work-card__body { padding: 26px clamp(20px,3vw,28px) 28px; display: flex; flex-direction: column; gap: 18px; }
434	.work-card__no { margin: 0; font-size: 11px; letter-spacing: 0.2em; color: #DC8541; }
435	.work-card__title { margin: 10px 0 0; font-weight: 700; font-size: 20px; line-height: 1.5; color: #172E4A; }
