/* ============================================
   philosophy（PHILOSOPHY）
   ============================================ */
.chain { display: flex; flex-direction: column; gap: 14px; align-items: stretch; max-width: 920px; margin: 0 auto; }
.chain__node { flex: 1; min-width: 0; background: #1E3A5C; color: #FFFFFF; border: 3px solid #E0B98F; border-radius: 22px; padding: clamp(22px,3vw,30px); text-align: center; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; }
.chain__node--accent { background: #FFFFFF; color: #172E4A; border: none; box-shadow: 8px 8px 0 #A85A1E; }
.chain__icon img { width: clamp(60px,8vw,92px); height: clamp(60px,8vw,92px); object-fit: contain; display: block; }
.chain__role { margin: 0; font-weight: 600; font-size: 13px; letter-spacing: 0.1em; color: inherit; }
.chain__node--accent .chain__role { color: #C06E2E; }
.chain__points { list-style: none; margin: 16px 0 0; padding: 0; display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; }
.chain__points .tag { font-size: 11px; padding: 6px 13px; background: rgba(23,46,74,0.08); }
.chain__arrow { display: none; }

.philosophy__points { list-style: none; margin: 22px 0 0; padding: 0; display: grid; gap: 12px; max-width: 40ch; }
.philosophy__points li { font-size: 14.5px; color: #FFFFFF; padding-left: 22px; position: relative; }
.philosophy__points li::before { content: ""; position: absolute; left: 0; top: 8px; width: 6px; height: 6px; border-radius: 50%; background: #DC8541; }

@media (min-width: 820px) {
  .chain { flex-direction: row; }
  .chain__arrow { display: flex; align-items: center; justify-content: center; flex: none; color: #DC8541; font-size: 18px; }
}

/* ============================================
   work-card（WORKS／クリックでモーダル詳細を開くポップカード）
   ============================================ */
.work-grid { display: grid; grid-template-columns: 1fr; gap: 26px; }
.work-card { display: flex; flex-direction: column; cursor: pointer; background: #FFFFFF; border: 3px solid #172E4A; border-radius: 26px; overflow: hidden; box-shadow: 8px 8px 0 #172E4A; transition: transform .2s ease; }
.work-card:hover { transform: translate(-2px,-2px); }
.work-card__media { position: relative; aspect-ratio: 4/3; background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px); overflow: hidden; }
.work-card__media img { display: block; width: 100%; height: 100%; object-fit: cover; }
.work-card__media--placeholder { display: flex; align-items: center; justify-content: center; }
.work-card__media--placeholder span { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 6px 12px; border: 1px solid #E3E6EB; border-radius: 999px; }
.work-card__body { padding: 26px clamp(20px,3vw,28px) 28px; display: flex; flex-direction: column; gap: 18px; }
.work-card__no { margin: 0; font-size: 11px; letter-spacing: 0.2em; color: #DC8541; }
.work-card__title { margin: 10px 0 0; font-weight: 700; font-size: 20px; line-height: 1.5; color: #172E4A; }
.work-card__field-label { margin: 0 0 8px; font-size: 10px; letter-spacing: 0.18em; color: #A7AFBC; text-transform: uppercase; }
.work-card__roles { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
.work-card__role { font-size: 12px; color: #3E4A5C; background: rgba(23,46,74,0.07); border-radius: 999px; padding: 5px 12px; white-space: nowrap; }
.work-card__text { margin: 0; font-size: 13px; line-height: 1.95; color: #56637A; }
.work-card__result { margin: 0; padding: 14px 18px; background: rgba(220,133,65,0.1); border-left: 10px solid #DC8541; border-radius: 14px; font-size: 13px; font-weight: 700; color: #A85A1E; line-height: 1.75; }
.work-card__result--stat { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; }
.work-card__result-pre { margin: 0; font-size: 12px; font-weight: 500; }
.work-card__result-num { font-size: clamp(32px,5vw,44px); font-weight: 900; line-height: 1; }
.work-card__result-unit { font-size: 13px; font-weight: 700; }
.work-card__result-note { margin: -6px 0 0; font-size: 11.5px; color: #8A93A3; }
.work-card__more { margin: 0; display: inline-flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 700; letter-spacing: 0.08em; color: #A85A1E; }

@media (min-width: 720px) {
  .work-grid { grid-template-columns: repeat(auto-fit,minmax(280px,1fr)); }
}

/* ============================================
   process-row（DIRECTION SAMPLE／番号バッジ入りカードのグリッド）
   ============================================ */
.process-row { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(280px,1fr)); gap: 12px; }
.process-row__item { display: flex; align-items: center; gap: 16px; padding: 20px 22px; border-radius: 20px; background: #FFFFFF; border: 3px solid #172E4A; }
.process-row__no { flex: none; width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; background: rgba(220,133,65,0.12); color: #C06E2E; }
.process-row__label { font-size: 14.5px; line-height: 1.7; font-weight: 500; color: #172E4A; }
.process-row__item--highlight { background: #A85A1E; }
.process-row__item--highlight .process-row__no { background: rgba(255,255,255,0.22); color: #FFFFFF; }
.process-row__item--highlight .process-row__label { color: #FFFFFF; }

/* ============================================
   sample-grid（DIRECTION SAMPLE／ディレクションサンプルのサムネイル）
   ============================================ */
.sample-grid { list-style: none; margin: 0 0 clamp(28px,4vw,40px); padding: 0; display: grid; grid-template-columns: repeat(2,1fr); gap: 14px; }
.sample-card { background: #FFFFFF; border: 3px solid #172E4A; border-radius: 20px; overflow: hidden; box-shadow: 6px 6px 0 #172E4A; }
.sample-card__thumb { aspect-ratio: 4/3; background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px); display: flex; align-items: center; justify-content: center; overflow: hidden; }
.sample-card__thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.sample-card__thumb-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 6px 12px; border: 1px solid #E3E6EB; border-radius: 999px; }
.sample-card__no { margin: 16px 18px 0; font-size: 11px; letter-spacing: 0.2em; color: #DC8541; }
.sample-card__title { margin: 6px 18px 18px; font-size: 13.5px; font-weight: 700; color: #172E4A; line-height: 1.6; }

@media (min-width: 640px) {
  .sample-grid { grid-template-columns: repeat(4,1fr); }
}

/* ============================================
   profile（PROFILE）
   ============================================ */
.profile__top { display: flex; flex-direction: column; align-items: center; gap: 22px; text-align: center; margin-bottom: clamp(40px,6vw,64px); }
.profile__photo { width: 160px; height: 200px; border-radius: 90px 90px 20px 20px; background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px); border: 2.5px solid #172E4A; display: flex; align-items: center; justify-content: center; overflow: hidden; }
.profile__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 10px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 5px 10px; border-radius: 999px; }
.profile__name { margin: 0; font-weight: 900; font-size: clamp(23px,2.8vw,30px); color: #172E4A; }
.profile__name-en { display: block; margin-top: 6px; font-size: 11px; letter-spacing: 0.2em; color: #A7AFBC; }
.profile__role { margin: 12px 0 0; font-size: 13px; color: #56637A; }

.stat-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px 12px; margin-top: clamp(36px,5vw,52px); }
.stat-grid > div { padding-top: 20px; border-top: 3px solid #DC8541; }
.stat__label { margin: 0; font-size: 10px; letter-spacing: 0.14em; color: #A7AFBC; }
.stat__value { margin: 10px 0 0; font-size: 13.5px; line-height: 1.8; color: #172E4A; }

.pull-quote { margin: clamp(36px,5vw,56px) 0 0; text-align: center; font-weight: 900; font-size: clamp(19px,2.6vw,28px); line-height: 1.75; color: #C06E2E; max-width: 32ch; }

/* ============================================
   cta-dark（最終CTA）
   ============================================ */
.section--cta { background: #172E4A; color: #FFFFFF; text-align: center; }
.cta__bubbles { justify-content: center; margin-top: clamp(28px,4vw,40px); }

